arguments.content:
/* Base reset and typography */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
}

body {
  font-family: 'Georgia', 'Times New Roman', serif;
  line-height: 1.6;
  color: #2c3e50;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

/* Site header */
.site-header {
  text-align: center;
  margin-bottom: 3rem;
}

.site-header h1 {
  font-size: 2.5rem;
  color: #ffd700;
  text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.5);
  margin-bottom: 0.5rem;
}

.site-header .subtitle {
  font-size: 1.125rem;
  color: #e0e0e0;
  font-style: italic;
}

/* Event grid layout */
.event-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
}

/* Event card styles */
.event-card {
  background: linear-gradient(145deg, #ffffff, #f0f0f0);
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  position: relative;
}

.event-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4);
}

.event-card.dawn {
  border-top: 6px solid #ff6b6b;
}

.event-card.dawn .event-badge {
  background: linear-gradient(135deg, #ff6b6b, #ffa502);
  color: white;
}

.event-card.lantern {
  border-top: 6px solid #4ecdc4;
}

.event-card.lantern .event-badge {
  background: linear-gradient(135deg, #4ecdc4, #45b7d8);
  color: white;
}

.event-card.concert {
  border-top: 6px solid #34495e;
}

.event-card.concert .event-badge.sold-out {
  background: linear-gradient(135deg, #e74c3c, #c0392b);
  color: white;
}

.event-card .event-badge {
  position: absolute;
  top: 1rem;
  right: 1rem;
  padding: 0.5rem 1rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
}

.event-card h2 {
  padding: 2.5rem 1.5rem 1rem;
  font-size: 1.5rem;
  color: #2c3e50;
}

.event-card .event-time,
.event-card .event-location {
  padding: 0 1.5rem;
  font-size: 0.9375rem;
  color: #7f8c8d;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.event-card .event-time {
  margin-top: 0.5rem;
}

.event-card .event-desc {
  padding: 1rem 1.5rem;
  font-size: 0.9375rem;
  color: #34495e;
}

/* Register buttons */
.register-btn {
  width: 100%;
  padding: 1rem;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  border-radius: 0 0 16px 16px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
}

.register-btn:hover {
  transform: scale(1.02);
  box-shadow: 0 5px 15px rgba(102, 126, 234, 0.4);
}

.register-btn:active {
  transform: scale(0.98);
}

.waitlist-btn {
  background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
}

.waitlist-btn:hover {
  box-shadow: 0 5px 15px rgba(44, 62, 80, 0.4);
}

/* Actions footer */
.actions-footer {
  text-align: center;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.show-sold-out-btn {
  padding: 0.875rem 2rem;
  background: linear-gradient(135deg, #f1c40f 0%, #f39c12 100%);
  color: #2c3e50;
  border: none;
  border-radius: 50px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 5px 15px rgba(243, 156, 18, 0.3);
}

.show-sold-out-btn:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 20px rgba(243, 156, 18, 0.5);
}

.show-sold-out-btn:active {
  transform: scale(0.98);
}

/* Hidden state for concert card */
.event-card.hidden {
  display: none;
}

/* Responsive adjustments for mobile (375px) */
@media screen and (max-width: 375px) {
  body {
    padding: 1.5rem 0.5rem;
  }

  .site-header h1 {
    font-size: 1.75rem;
  }

  .site-header .subtitle {
    font-size: 1rem;
  }

  .event-grid {
    grid-template-columns: 1fr;
    gap: 1.5rem;
  }

  .event-card h2 {
    font-size: 1.25rem;
  }

  .register-btn {
    padding: 0.875rem;
    font-size: 0.9375rem;
  }

  .show-sold-out-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.9375rem;
  }
}

/* Accessibility improvements */
.show-sold-out-btn:focus-visible,
.register-btn:focus-visible {
  outline: 3px solid #667eea;
  outline-offset: 2px;
}

/* Print styles */
@media print {
  .site-header h1 {
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
}

/**
 * Night Garden FLEET Event Website
 * Handles the "Show sold out" button functionality
 */

(function() {
  'use strict';

  // DOM elements
  const showSoldOutBtn = document.getElementById('show-sold-out');
  const concertCard = document.getElementById('concert-card');

  /**
   * Show the hidden concert card
   */
  function showSoldOutCard() {
    if (!concertCard) return;

    concertCard.classList.remove('hidden');

    // Announce to screen readers
    announceToScreenReader('Midnight sold-out concert has been revealed');

    // Optional: scroll to the card
    concertCard.scrollIntoView({
      behavior: 'smooth',
      block: 'center'
    });

    // Disable the button after revealing
    if (showSoldOutBtn) {
      showSoldOutBtn.disabled = true;
      showSoldOutBtn.textContent = 'Sold-out concert revealed';
    }
  }

  /**
   * Announce message to screen readers
   * @param {string} message - Message to announce
   */
  function announceToScreenReader(message) {
    // Create or get the announcement element
    let announcer = document.getElementById('sr-announcer');

    if (!announcer) {
      announcer = document.createElement('div');
      announcer.id = 'sr-announcer';
      announcer.setAttribute('role', 'status');
      announcer.setAttribute('aria-live', 'polite');
      announcer.setAttribute('aria-atomic', 'true');
      announcer.style.cssText = `
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      `;
      document.body.appendChild(announcer);
    }

    // Clear previous message and set new one
    announcer.textContent = '';
    setTimeout(() => {
      announcer.textContent = message;
    }, 50);
  }

  /**
   * Initialize event listeners
   */
  function init() {
    // Add click event to show sold-out button
    if (showSoldOutBtn) {
      showSoldOutBtn.addEventListener('click', showSoldOutCard);
    }

    // Keyboard accessibility: allow Enter and Space keys
    if (showSoldOutBtn) {
      showSoldOutBtn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          showSoldOutCard();
        }
      });
    }
  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  // Expose function globally for testing
  window.showSoldOutCard = showSoldOutCard;

})();
